Algoritmo DrawBoard
  Dimension board[3, 3] Como Entero;
  board[0, 0] <- 1;
  board[0, 1] <- 2;
  board[0, 2] <- 1;
  board[1, 0] <- 2;
  board[1, 1] <- 1;
  board[1, 2] <- 2;
  board[2, 0] <- 2;
  board[2, 1] <- 1;
  board[2, 2] <- 1;
  Para r <- 0 Hasta 2 Hacer
    Definir line Como Cadena <- "";
    Para c <- 0 Hasta 2 Hacer
      Segun board[r, c] Hacer
        1:
          line <- line + "X";
        2:
          line <- line + "O";
        De Otro Modo:
          line <- line + ".";
      FinSegun
    FinPara
    Escribir line;
  FinPara
FinAlgoritmo

Algoritmo NoughtsAndCrosses
  Dimension t[3, 3] Como Entero;
  Para r <- 0 Hasta 2 Hacer
    Para c <- 0 Hasta 2 Hacer
      Leer t[r, c];
    FinPara
  FinPara
  Definir winner Como Entero <- 0;
  Para i <- 0 Hasta 2 Hacer
    Si t[i, 0] <> 0 Y t[i, 0] = t[i, 1] Y t[i, 1] = t[i, 2] Entonces
      winner <- t[i, 0];
    FinSi
    Si t[0, i] <> 0 Y t[0, i] = t[1, i] Y t[1, i] = t[2, i] Entonces
      winner <- t[0, i];
    FinSi
  FinPara
  Si t[1, 1] <> 0 Y t[0, 0] = t[1, 1] Y t[1, 1] = t[2, 2] Entonces
    winner <- t[1, 1];
  FinSi
  Si t[1, 1] <> 0 Y t[0, 2] = t[1, 1] Y t[1, 1] = t[2, 0] Entonces
    winner <- t[1, 1];
  FinSi
  Segun winner Hacer
    1:
      Escribir "X wins";
    2:
      Escribir "O wins";
    De Otro Modo:
      Escribir "Nobody";
  FinSegun
FinAlgoritmo
